import { gsap } from 'gsap';
import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, DirectionalLight, Vector3 } = ctx.THREE;

  // Root object for this node
  const root = new Group();

  // Store references for cleanup
  const activePrimitives = [];
  let hoverTimeline = null;

  // Load GLB mesh (async, but function stays synchronous)
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    });
  }

  // Apply cinematic primitives listed in config
  const primitivesList = config.cinematicPrimitives ?? [];
  for (const p of primitivesList) {
    const apply = ctx.primitives[p.name];
    if (apply) {
      const instance = apply(root, p.params);
      activePrimitives.push(instance);
    }
  }

  // Accent rim light (using spec accent color)
  const rimLight = new DirectionalLight('#ff2a38', 0.8);
  rimLight.position.set(0, 0, 1);
  root.add(rimLight);

  // Event handlers container
  root.userData.handlers = {};

  // Hover effect: subtle rise‑in (0.15 scene units)
  root.userData.handlers.hover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: root.position.y + 0.15,
      duration: 0.15,
      ease: 'power2.out',
    });
  };

  // Click effect: emit navigation event
  root.userData.handlers.click = () => {
    ctx.emit('hub-journal.select', {});
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    if (hoverTimeline) hoverTimeline.kill();

    // Cleanup primitives
    for (const p of activePrimitives) {
      if (p.cleanup) p.cleanup();
    }

    // Dispose of GLB resources if they exist
    // (Assumes GLTF loader attaches .scene with .traverse for disposal)
    root.traverse((obj) => {
      if (obj.isMesh && obj.geometry) obj.geometry.dispose();
      if (obj.isMesh && obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose && m.dispose());
        } else {
          obj.material.dispose && obj.material.dispose();
        }
      }
    });
  };

  return root;
}
